-- Classic 1.60: quest map areas (POI shapes) for 4065 vanilla quests without any, from the WotLK 3.3.5 data of AzerothCore
-- (classic_re/sniff/wotlk_quest_poi.py). Only the turn-in and objectives whose target is the same creature / object / item as in
-- our quest; Eastern Kingdoms and Kalimdor only. Rows are VerifiedBuild 12340; quests with POIs from any other source (sniffs) are
-- never touched. Safe to run again.
DROP TEMPORARY TABLE IF EXISTS `tmp_wotlk_poi`;
CREATE TEMPORARY TABLE `tmp_wotlk_poi` LIKE `quest_poi`;
DROP TEMPORARY TABLE IF EXISTS `tmp_wotlk_poi_points`;
CREATE TEMPORARY TABLE `tmp_wotlk_poi_points` LIKE `quest_poi_points`;
-- quests that got POIs from another source since: drop ours
DELETE t FROM `tmp_wotlk_poi` t WHERE EXISTS (SELECT 1 FROM `quest_poi` p WHERE p.`QuestID` = t.`QuestID` AND p.`VerifiedBuild` <> 12340);
DELETE t FROM `tmp_wotlk_poi_points` t WHERE NOT EXISTS (SELECT 1 FROM `tmp_wotlk_poi` p WHERE p.`QuestID` = t.`QuestID`);
DELETE FROM `quest_poi` WHERE `VerifiedBuild` = 12340 AND `QuestID` IN (SELECT `QuestID` FROM `tmp_wotlk_poi`);
DELETE FROM `quest_poi_points` WHERE `VerifiedBuild` = 12340 AND `QuestID` IN (SELECT DISTINCT `QuestID` FROM `tmp_wotlk_poi`);
DROP TEMPORARY TABLE `tmp_wotlk_poi`;
DROP TEMPORARY TABLE `tmp_wotlk_poi_points`;
